:root {
  color-scheme: light;
  --bg: #f5f9f8;
  --panel: #ffffff;
  --ink: #082441;
  --muted: #536575;
  --line: #d9dee5;
  --teal: #007d79;
  --teal-dark: #007d79;
  --amber: #b7791f;
  --red: #b42318;
  --blue: #164e9f;
  --green: #15803d;
  --yellow: #a16207;
  --shadow: 0 18px 45px rgba(24, 33, 43, 0.08);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

/* Alerta modal temporal para confirmaciones y errores del flujo de mezclas. */
.native-shell .doctor-sweet-alert {
  position: fixed;
  inset: 0;
  z-index: 250;
  display: grid;
  place-items: center;
  padding: 20px;
  animation: doctor-sweet-alert-in 180ms ease-out;
}

.native-shell .doctor-sweet-alert.is-closing {
  opacity: 0;
  transition: opacity 180ms ease;
}

.native-shell .doctor-sweet-alert-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
  border-radius: 0;
  background: rgba(15, 35, 42, 0.48);
  box-shadow: none;
  cursor: default;
}

.native-shell .doctor-sweet-alert-card {
  position: relative;
  z-index: 1;
  width: min(430px, 100%);
  padding: 28px 30px 24px;
  border: 1px solid #d6e2e4;
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 22px 54px rgba(20, 49, 58, 0.22);
  text-align: center;
}

.native-shell .doctor-sweet-alert-icon {
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  margin: 0 auto 16px;
  border: 3px solid currentColor;
  border-radius: 50%;
  font-size: 31px;
  font-weight: 700;
}

.native-shell .doctor-sweet-alert-success .doctor-sweet-alert-icon { color: #0aae9d; }
.native-shell .doctor-sweet-alert-error .doctor-sweet-alert-icon { color: #e04e55; }
.native-shell .doctor-sweet-alert-card h2 { margin: 0 0 9px; color: #082441; font-size: 21px; }
.native-shell .doctor-sweet-alert-card p { margin: 0; color: #526b78; line-height: 1.55; }

.native-shell .doctor-sweet-alert-confirm {
  min-width: 112px;
  margin-top: 21px;
  padding: 10px 18px;
  border: 1px solid #08a99b;
  border-radius: 8px;
  background: #08a99b;
  color: #fff;
  font-weight: 800;
}

@keyframes doctor-sweet-alert-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

* {
  box-sizing: border-box;
}

body {
  min-height: 100vh;
  margin: 0;
  background: var(--bg);
  color: var(--ink);
}

a {
  color: inherit;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 72px;
  padding: 14px clamp(18px, 4vw, 48px);
  background: rgba(255, 255, 255, 0.92);
  border-bottom: 1px solid var(--line);
  backdrop-filter: blur(16px);
}

.brand,
.session {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand {
  text-decoration: none;
  flex: 0 0 auto;
}

.brand-mark {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 8px;
  background: var(--teal);
  color: #fff;
  font-weight: 800;
}

.brand strong,
.brand small {
  display: block;
}

.brand small,
.session {
  color: var(--muted);
  font-size: 14px;
}

.session form {
  margin: 0;
}

.module-nav {
  display: flex;
  flex: 1 1 auto;
  gap: 6px;
  overflow-x: auto;
  padding: 4px;
  scrollbar-width: thin;
}

.module-nav a {
  flex: 0 0 auto;
  min-height: 34px;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 7px 10px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
  text-decoration: none;
  white-space: nowrap;
}

.module-nav a:hover,
.module-nav a:focus {
  border-color: var(--line);
  background: #fff;
  color: var(--ink);
}

button,
.primary-button,
.bridge-panel a {
  min-height: 42px;
  border: 0;
  border-radius: 8px;
  padding: 0 16px;
  background: var(--teal);
  color: #fff;
  font: inherit;
  font-weight: 700;
  text-decoration: none;
  cursor: pointer;
}

.session button {
  background: #263241;
}

.shell {
  width: min(1180px, calc(100% - 32px));
  margin: 0 auto;
  padding: 36px 0 56px;
}

.login-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 420px);
  gap: clamp(24px, 6vw, 72px);
  align-items: center;
  min-height: calc(100vh - 160px);
}

.login-copy h1,
.page-heading h1,
.bridge-panel h1 {
  margin: 0;
  font-size: clamp(34px, 5vw, 60px);
  line-height: 1.02;
  letter-spacing: 0;
}

.login-copy p,
.page-heading p,
.bridge-panel p {
  color: var(--muted);
  font-size: 17px;
  line-height: 1.6;
}

.eyebrow {
  margin: 0 0 12px;
  color: var(--teal-dark);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: uppercase;
}

.status-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 24px;
}

.status-strip span,
.section-title span {
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 8px 12px;
  background: #fff;
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
}

.login-panel {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  box-shadow: var(--shadow);
}

.login-panel form {
  display: grid;
  gap: 18px;
  padding: 24px;
}

label {
  display: grid;
  gap: 8px;
  color: var(--muted);
  font-size: 14px;
  font-weight: 700;
}

select,
input {
  width: 100%;
  min-height: 46px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0 12px;
  background: #fff;
  color: var(--ink);
  font: inherit;
}

textarea {
  width: 100%;
  min-height: 92px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: #fff;
  color: var(--ink);
  font: inherit;
  resize: vertical;
}

.alert {
  border-left: 4px solid var(--red);
  border-radius: 8px;
  padding: 12px;
  background: #fff4f2;
  color: var(--red);
  font-size: 14px;
  font-weight: 700;
}

.action-link,
.secondary-button {
  display: inline-grid;
  place-items: center;
  min-height: 42px;
  border-radius: 8px;
  padding: 0 16px;
  font-weight: 800;
  text-decoration: none;
}

.secondary-button {
  border: 1px solid var(--line);
  background: #fff;
  color: var(--ink);
}

.text-link {
  color: var(--blue);
  font-weight: 800;
  text-decoration: none;
}

.insurance-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 22px;
}

.insurance-nav a {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px 12px;
  background: #fff;
  color: #334155;
  font-size: 13px;
  font-weight: 800;
  text-decoration: none;
}

.insurance-nav a:hover {
  border-color: var(--blue);
  color: var(--blue);
}

.notice {
  margin-bottom: 18px;
  border-radius: 8px;
  padding: 14px 16px;
  font-weight: 700;
}

.notice ul {
  margin: 8px 0 0;
  padding-left: 18px;
}

.notice.success {
  border: 1px solid #bbf7d0;
  background: #f0fdf4;
  color: #166534;
}

.notice.danger {
  border: 1px solid #fecaca;
  background: #fff1f2;
  color: var(--red);
}

.insurance-metrics {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.insurance-grid {
  display: grid;
  gap: 16px;
  margin-top: 18px;
}

.insurance-grid.two-col {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.insurance-panel,
.table-card,
.form-section {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
}

.insurance-panel {
  padding: 18px;
}

.compact-list,
.alert-list,
.timeline {
  display: grid;
  gap: 10px;
}

.compact-list.separated {
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
}

.compact-list div,
.compact-list a,
.alert-row,
.timeline div {
  display: grid;
  gap: 4px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: #fafafa;
  text-decoration: none;
}

.compact-list span,
.alert-row span,
.timeline span,
.timeline time,
.detail-list dt {
  color: var(--muted);
  font-size: 13px;
}

.alert-row.warning {
  border-color: #fde68a;
  background: #fffbeb;
}

.alert-row.critical {
  border-color: #fecaca;
  background: #fff1f2;
}

.empty-state {
  margin: 0;
  color: var(--muted);
}

.filter-bar,
.insurance-form,
.inline-form {
  display: grid;
  gap: 14px;
}

.filter-bar {
  grid-template-columns: repeat(5, minmax(0, 1fr));
  align-items: end;
  margin-bottom: 16px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 14px;
  background: #fff;
}

.insurance-form {
  margin-bottom: 20px;
}

.insurance-form.compact {
  margin-top: 0;
}

.form-section {
  display: grid;
  gap: 16px;
  padding: 18px;
}

.form-section h2 {
  margin: 0;
  font-size: 19px;
}

.form-grid,
.inline-form {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.span-2 {
  grid-column: 1 / -1;
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

.checkbox-line {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 46px;
}

.checkbox-line input {
  width: auto;
  min-height: auto;
}

.record-header,
.record-actions,
.record-summary {
  display: flex;
  gap: 12px;
}

.record-header {
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 18px;
}

.record-header h1 {
  margin: 0;
  font-size: clamp(32px, 4vw, 48px);
  letter-spacing: 0;
}

.record-header p {
  color: var(--muted);
}

.record-actions {
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
}

.record-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-bottom: 18px;
}

.record-summary article {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 14px;
  background: #fff;
}

.record-summary span {
  display: block;
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
}

.detail-list {
  display: grid;
  gap: 10px;
  margin: 0;
}

.detail-list div {
  display: grid;
  grid-template-columns: 150px 1fr;
  gap: 10px;
  border-bottom: 1px solid var(--line);
  padding-bottom: 8px;
}

.detail-list dd {
  margin: 0;
}

.badge {
  display: inline-grid;
  width: max-content;
  min-height: 28px;
  place-items: center;
  border-radius: 999px;
  padding: 0 10px;
  background: #eef2f7;
  color: #344054;
  font-size: 12px;
  font-weight: 900;
  text-transform: uppercase;
}

.risk-low {
  background: #dcfce7;
  color: #166534;
}

.risk-medium {
  background: #fef9c3;
  color: #854d0e;
}

.risk-high {
  background: #ffedd5;
  color: #9a3412;
}

.risk-critical {
  background: #fee2e2;
  color: #991b1b;
}

.table-card {
  overflow-x: auto;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 760px;
}

.data-table th,
.data-table td {
  border-bottom: 1px solid var(--line);
  padding: 13px 14px;
  text-align: left;
  vertical-align: top;
}

.data-table th {
  background: #f8fafc;
  color: #475467;
  font-size: 12px;
  text-transform: uppercase;
}

.data-table td span {
  display: block;
  color: var(--muted);
  font-size: 13px;
}

.table-action {
  display: grid;
  grid-template-columns: minmax(120px, 1fr) minmax(140px, 1fr) auto;
  gap: 8px;
  align-items: center;
}

.table-action select,
.table-action input,
.table-action button {
  min-height: 36px;
}

.pagination-wrap {
  margin-top: 14px;
}

.pagination-wrap nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  color: var(--muted);
  font-size: 13px;
}

.pagination-wrap nav > div {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.pagination-wrap a,
.pagination-wrap span[aria-current],
.pagination-wrap span[aria-disabled] span,
.pagination-wrap a[rel],
.pagination-wrap span.relative {
  min-width: 34px;
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: #fff;
  color: var(--text);
  padding: 0 10px;
  text-decoration: none;
  font-size: 13px;
  font-weight: 800;
}

.pagination-wrap span[aria-current] span,
.pagination-wrap [aria-current="page"] span {
  border-color: var(--primary);
  background: var(--primary);
  color: #fff;
}

.pagination-wrap svg {
  width: 18px;
  height: 18px;
  max-width: 18px;
  max-height: 18px;
  display: block;
  flex: 0 0 18px;
}

.permission-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.permission-grid span {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
  background: #fafafa;
  font-size: 13px;
  font-weight: 700;
}

.page-heading {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 26px;
}

.metric-grid,
.module-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.metric-card,
.module-card {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
}

.metric-card {
  display: grid;
  gap: 8px;
  min-height: 112px;
  padding: 18px;
}

.metric-card span,
.module-card small {
  color: var(--muted);
  font-size: 13px;
}

.metric-card strong {
  font-size: 34px;
  line-height: 1;
}

.module-section {
  margin-top: 32px;
}

.section-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}

.section-title h2 {
  margin: 0;
}

.module-card {
  position: relative;
  display: grid;
  gap: 8px;
  min-height: 104px;
  padding: 18px;
  text-decoration: none;
}

.module-card.module-card-priority-high {
  border-top: 3px solid #0f9f8f;
}

.module-card.module-card-priority-medium {
  border-top: 3px solid #e2a526;
}

.module-card > span:not(.module-priority-mark) {
  padding-right: 112px;
}

.module-priority-mark {
  position: absolute;
  top: 12px;
  right: 12px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 8px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
}

.module-priority-mark i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

.module-card-priority-high .module-priority-mark {
  background: #e7f8f3;
  color: #007d79;
}

.module-card-priority-medium .module-priority-mark {
  background: #fff5d9;
  color: #a56b00;
}

.module-card:hover {
  border-color: var(--teal);
  box-shadow: var(--shadow);
}

.module-card span {
  font-weight: 800;
}

.module-card-access {
  width: fit-content;
  margin-top: 4px;
  padding: 7px 14px;
  border: 1px solid #007d79;
  border-radius: 7px;
  background: #fff;
  color: #007d79;
  font-size: 12px;
  font-weight: 800;
  line-height: 1;
}

.module-card:hover .module-card-access {
  background: #007d79;
  color: #fff;
}

.bridge-screen {
  display: grid;
  min-height: 100vh;
  place-items: center;
  padding: 24px;
}

.bridge-panel {
  width: min(520px, 100%);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 28px;
  background: #fff;
  box-shadow: var(--shadow);
}

.bridge-panel a {
  display: inline-grid;
  place-items: center;
}

.patient-hero {
  align-items: center;
}

.doctor-hero {
  align-items: center;
}

.orders-hero {
  align-items: center;
}

.pharmacy-hero {
  align-items: center;
}

.patient-summary article strong {
  display: block;
  margin-top: 6px;
  font-size: 26px;
}

.doctor-summary article strong {
  display: block;
  margin-top: 6px;
  font-size: 26px;
}

.orders-summary article strong {
  display: block;
  margin-top: 6px;
  font-size: 26px;
}

.orders-layout {
  display: grid;
  gap: 18px;
}

.orders-filter {
  grid-template-columns: minmax(0, 1fr) auto auto;
}

.orders-product-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.orders-product-card {
  display: grid;
  gap: 16px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 16px;
  background: #fff;
}

.orders-product-card h3 {
  margin: 10px 0 6px;
  font-size: 19px;
}

.orders-product-card p {
  margin: 0;
  color: var(--muted);
  line-height: 1.45;
}

.orders-product-meta {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin: 0;
}

.orders-product-meta div {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 9px;
  background: #fafafa;
}

.orders-product-meta dt {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
  text-transform: uppercase;
}

.orders-product-meta dd {
  margin: 4px 0 0;
  font-weight: 900;
}

.orders-product-form {
  display: grid;
  grid-template-columns: 0.7fr 1fr 1fr;
  gap: 10px;
}

.orders-product-form button {
  grid-column: 1 / -1;
}

.orders-list article {
  gap: 12px;
}

.orders-list-heading {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.orders-items {
  display: grid;
  gap: 5px;
  color: var(--muted);
}

.pharmacy-layout {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-top: 18px;
}

.pharmacy-metrics {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.pharmacy-filter {
  grid-template-columns: minmax(0, 1fr) auto;
}

.pharmacy-status-form {
  grid-template-columns: minmax(120px, 1fr) minmax(160px, 1fr) auto;
}

.messenger-layout {
  display: grid;
  grid-template-columns: minmax(260px, 330px) minmax(0, 1fr);
  gap: 18px;
  align-items: start;
  margin-top: 18px;
}

.messenger-metrics {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.messenger-profile-card {
  position: sticky;
  top: 94px;
  display: grid;
  gap: 18px;
}

.messenger-route-list {
  display: grid;
  gap: 14px;
}

.messenger-route-list article {
  display: grid;
  gap: 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 14px;
  background: #fff;
}

.messenger-route-header {
  gap: 12px;
  margin: 0;
}

.messenger-route-header span,
.messenger-last-report,
.messenger-items {
  color: var(--muted);
}

.messenger-route-detail {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.messenger-items {
  display: grid;
  gap: 4px;
  font-size: 14px;
}

.messenger-status-form {
  grid-template-columns: minmax(130px, 0.7fr) minmax(180px, 1fr) auto;
}

.messenger-reports {
  grid-column: 2;
}

.operational-layout {
  display: grid;
  grid-template-columns: minmax(260px, 330px) minmax(0, 1fr);
