/* Native Laravel visual parity layer. These rules keep the established
   product look while using maintainable Blade components. */
.native-shell {
  background:
    radial-gradient(circle at 14% 0%, rgba(36, 217, 198, 0.08), transparent 28%),
    linear-gradient(180deg, #fbfefe 0%, #f5fafb 54%, #f7fbfa 100%);
}

.native-shell .topbar {
  position: sticky;
  top: 10px;
  width: min(1380px, calc(100% - 24px));
  min-height: 72px;
  margin: 10px auto 0;
  padding: 12px 18px;
  border: 1px solid #e5eef1;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 14px 38px rgba(31, 45, 52, 0.08);
  backdrop-filter: blur(16px);
}

.native-shell .brand {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr);
  grid-template-rows: auto auto;
  align-items: center;
  gap: 3px 12px;
  min-width: 220px;
}

.native-shell .brand-mark {
  width: 46px;
  height: 46px;
  grid-row: 1 / 3;
  border-radius: 14px;
  background: linear-gradient(135deg, #24d9c6 0%, #069985 100%);
  box-shadow: 0 14px 24px rgba(20, 199, 183, 0.2);
  font-size: 24px;
}

.native-shell .brand strong {
  color: #344156;
  font-size: 16px;
  font-weight: 850;
  line-height: 1.1;
}

.native-shell .brand small {
  color: var(--teal-dark);
  font-size: 12px;
  font-weight: 800;
}

.native-shell .module-nav {
  gap: 8px;
  padding: 4px;
}

.native-shell .module-nav a {
  min-height: 38px;
  border: 1px solid transparent;
  border-radius: 12px;
  padding: 10px 12px;
  color: #5f6d75;
  font-size: 12px;
  font-weight: 850;
}

.native-shell .module-nav a:hover,
.native-shell .module-nav a:focus {
  border-color: #dce9ed;
  background: #f4fbfa;
  color: var(--teal-dark);
}

.native-shell .session {
  gap: 10px;
}

.native-shell .session-badge {
  max-width: 220px;
  overflow: hidden;
  color: #65728b;
  font-size: 13px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.native-shell .session button {
  min-height: 38px;
  border: 1px solid #dce9ed;
  border-radius: 12px;
  background: #fff;
  color: #344156;
  box-shadow: 0 10px 24px rgba(31, 45, 52, 0.05);
}

.native-shell .session button:hover {
  border-color: #b8e8e5;
  background: #effcf9;
  color: var(--teal-dark);
}

.native-shell .shell {
  width: min(1380px, calc(100% - 24px));
  margin: 0 auto;
  padding: 16px 0 24px;
}

.native-shell .page-heading,
.native-shell .record-header {
  position: relative;
  overflow: hidden;
  border: 1px solid #e5eef1;
  border-radius: 22px;
  padding: 24px;
  background: linear-gradient(180deg, #ffffff 0%, #fbfefe 100%);
  box-shadow: 0 18px 48px rgba(33, 38, 36, 0.09);
}

.native-shell .page-heading::before,
.native-shell .record-header::before {
  position: absolute;
  inset: 0 auto 0 0;
  width: 5px;
  background: linear-gradient(180deg, #24d9c6 0%, #069985 100%);
  content: "";
}

.native-shell .eyebrow {
  color: var(--teal-dark);
  font-size: 11px;
  font-weight: 900;
}

.native-shell .page-heading h1,
.native-shell .record-header h1 {
  color: #344156;
  font-size: clamp(30px, 3.4vw, 46px);
  font-weight: 850;
  line-height: 1.05;
}

.native-shell .page-heading p,
.native-shell .record-header p {
  max-width: 760px;
  color: #65728b;
  font-size: 15px;
}

.native-shell .dashboard-logout-form {
  position: relative;
  z-index: 1;
  align-self: flex-start;
}

.native-shell .dashboard-logout-button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 42px;
  padding: 10px 15px;
  border: 1px solid #d7e4e7;
  border-radius: 10px;
  background: #fff;
  color: #344156;
  font-size: 13px;
  font-weight: 800;
  box-shadow: 0 8px 20px rgba(31, 45, 52, 0.07);
}

.native-shell .dashboard-logout-button:hover {
  border-color: #0c9e91;
  color: #087f76;
}

.native-shell .dashboard-logout-button svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.8;
}

.native-shell .metric-card,
.native-shell .module-card,
.native-shell .insurance-panel,
.native-shell .table-card,
.native-shell .form-section,
.native-shell .record-summary article,
.native-shell .orders-product-card {
  border: 1px solid #e5eef1;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 12px 30px rgba(31, 45, 52, 0.06);
}

.native-shell .metric-card {
  min-height: 124px;
  padding: 20px;
}

.native-shell .metric-card span,
.native-shell .module-card small,
.native-shell .record-summary span {
  color: #65728b;
  font-size: 12px;
  font-weight: 850;
  text-transform: uppercase;
}

.native-shell .metric-card strong,
.native-shell .record-summary article strong {
  color: #26323f;
  font-weight: 900;
}

.native-shell .module-card {
  min-height: 118px;
  border-radius: 16px;
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease;
}

.native-shell .module-card:hover {
  border-color: #b8e8e5;
  box-shadow: 0 18px 42px rgba(31, 45, 52, 0.1);
  transform: translateY(-2px);
}

.native-shell .module-card.module-card-priority-high {
  border-top: 3px solid #0f9f8f;
}

.native-shell .module-card.module-card-priority-medium {
  border-top: 3px solid #e2a526;
}

.native-shell .module-card.module-card-priority-high .module-priority-mark {
  background: #e7f8f3;
  color: #007d79;
}

.native-shell .module-card.module-card-priority-medium .module-priority-mark {
  background: #fff5d9;
  color: #a56b00;
}

.native-shell .module-card span,
.native-shell .section-title h2,
.native-shell .compact-title h2 {
  color: #344156;
  font-weight: 850;
}

.native-shell .section-title span {
  border-color: #dce9ed;
  background: #f7fbfa;
  color: var(--teal-dark);
}

.native-shell .compact-list div,
.native-shell .compact-list a,
.native-shell .alert-row,
.native-shell .timeline div {
  border-color: #e5eef1;
  border-radius: 14px;
  background: #fbfefe;
}

.native-shell .data-table th {
  background: #f7fbfa;
  color: #66706d;
  font-size: 11px;
  font-weight: 900;
}

.native-shell .data-table td {
  background: #fff;
}

.native-shell .badge {
  min-height: 26px;
  border: 1px solid #dce9ed;
  background: #effcf9;
  color: var(--teal-dark);
}

.native-shell button,
.native-shell .primary-button,
.native-shell .secondary-button,
.native-shell .action-link {
  border-radius: 12px;
  font-weight: 850;
}

.native-shell .primary-button,
.native-shell button:not(.icon-button) {
  background: linear-gradient(135deg, #0d766c 0%, #069985 100%);
  box-shadow: 0 12px 22px rgba(20, 199, 183, 0.16);
}

.native-shell .secondary-button,
.native-shell .action-link {
  border: 1px solid #dce9ed;
  background: #fff;
  color: #344156;
}

.native-shell input,
.native-shell select,
.native-shell textarea {
  border-color: #dce9ed;
  border-radius: 12px;
  background: #fbfefe;
}

.native-shell .login-grid {
  min-height: calc(100vh - 126px);
  align-items: center;
  padding: 18px 0;
}

.native-shell .login-copy {
  position: relative;
  border: 1px solid #e5eef1;
  border-radius: 22px;
  padding: clamp(24px, 4vw, 44px);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(251, 254, 254, 0.94));
  box-shadow: 0 18px 48px rgba(33, 38, 36, 0.09);
}

.native-shell .login-copy h1 {
  color: #344156;
  font-size: clamp(42px, 6vw, 72px);
  font-weight: 850;
}

.native-shell .login-copy p {
  max-width: 680px;
  color: #65728b;
}

.native-shell .login-panel {
  overflow: hidden;
  border-color: #e5eef1;
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 18px 48px rgba(33, 38, 36, 0.1);
}

.native-shell .login-panel-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 22px 24px 0;
}

.native-shell .login-panel-header h2 {
  margin: 2px 0 0;
  color: #344156;
  font-size: 20px;
}

.native-shell .login-mark {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  border-radius: 14px;
  background: linear-gradient(135deg, #24d9c6 0%, #069985 100%);
  color: #fff;
  box-shadow: 0 14px 24px rgba(20, 199, 183, 0.2);
  font-size: 24px;
  font-weight: 900;
}

