.formal-login-welcome::before { position: absolute; top: 10px; left: 50%; z-index: -1; width: min(540px, 70vw); height: 300px; background-image: radial-gradient(rgba(20,199,183,.28) 1px, transparent 1.5px); background-size: 13px 13px; content: ""; mask-image: radial-gradient(ellipse at center, #000 0%, rgba(0,0,0,.78) 46%, transparent 72%); opacity: .58; transform: translateX(-50%); }
.formal-login-welcome::after { position: absolute; top: 54px; left: 50%; color: #14c7b7; content: "+"; font-size: 38px; font-weight: 900; transform: translateX(-50%); }
