  mask-image: linear-gradient(0deg, rgba(0,0,0,.96) 0%, rgba(0,0,0,.74) 36%, rgba(0,0,0,.38) 64%, rgba(0,0,0,.12) 84%, rgba(0,0,0,0) 100%);
  -webkit-backdrop-filter: blur(18px) saturate(135%);
