.native-shell .patient-portal-topbar { position: sticky; top: 4px; z-index: 30; display: grid; grid-template-columns: 52px minmax(0, 1fr) 48px; gap: 9px; align-items: center; min-height: 70px; width: calc(100% - 8px); margin: 4px; padding: 5px 10px 5px 5px; box-sizing: border-box; background: rgba(255,255,255,.98); border: 1px solid #dce9eb; border-radius: 22px; box-shadow: 0 13px 30px rgba(34,78,85,.10); }
