.native-shell .patient-prescriptions-panel { width: 100%; max-width: 100%; min-width: 0; overflow: hidden; border: 1px solid #dce8ed; border-radius: 22px; background: #fff; box-shadow: 0 22px 50px rgba(16,42,60,.07); }
.native-shell .patient-prescriptions-hero { position: relative; display: flex; align-items: center; gap: 26px; min-height: 150px; padding: 26px 40px; overflow: hidden; border-bottom: 1px solid #dce8ed; background: linear-gradient(110deg,rgba(255,255,255,.94) 8%,rgba(238,253,250,.8) 60%,rgba(255,255,255,.9)); }
.native-shell .patient-prescriptions-hero::before { content: ""; position: absolute; inset: -260px -40px -240px 390px; opacity: .62; background: repeating-radial-gradient(ellipse at 62% 48%,transparent 0 10px,rgba(39,205,190,.22) 11px 12px); transform: rotate(-4deg); pointer-events: none; }
.native-shell .patient-prescriptions-hero > * { position: relative; z-index: 1; }
.native-shell .patient-prescriptions-hero-icon { display: grid; flex: 0 0 86px; place-items: center; width: 86px; height: 86px; border: 1px solid #bfe9e4; border-radius: 20px; background: #edfcf9; color: #087f74; }
.native-shell .patient-prescriptions-hero-icon span { position: relative; width: 34px; height: 42px; border: 4px solid currentColor; border-radius: 3px; }
.native-shell .patient-prescriptions-hero-icon span::before { content: ""; position: absolute; top: -4px; right: -4px; width: 13px; height: 13px; border-left: 4px solid currentColor; border-bottom: 4px solid currentColor; background: #edfcf9; }
.native-shell .patient-prescriptions-hero-icon span::after { content: ""; position: absolute; left: 8px; bottom: 9px; width: 14px; height: 4px; border-top: 3px solid currentColor; border-bottom: 3px solid currentColor; }
.native-shell .patient-prescriptions-hero h1 { margin: 0; color: #071833; font-size: clamp(34px,3vw,48px); line-height: 1; }
.native-shell .patient-prescriptions-redesign { display: grid; gap: 18px; padding: 20px 18px 28px; background: #fff; }
.native-shell .patient-prescription-filter-bar { display: flex; align-items: stretch; gap: 14px; min-width: 0; overflow-x: auto; padding: 2px 2px 18px; scrollbar-width: none; overscroll-behavior-x: contain; touch-action: pan-x; cursor: grab; -webkit-overflow-scrolling: touch; }
.native-shell .patient-prescription-filter-bar::-webkit-scrollbar { display: none; }
.native-shell .patient-prescription-filter { --prescription-filter-color: #007d79; position: relative; display: grid; flex: 0 0 128px; width: 128px; min-height: 118px; place-items: center; align-content: center; gap: 12px; padding: 16px 12px; border: 1px solid #d8e6ec !important; border-radius: 18px; background: #fff !important; color: #082441; font: inherit; font-size: 20px; font-weight: 950; text-align: center; white-space: nowrap; box-shadow: none !important; cursor: pointer; overflow: hidden; scroll-snap-align: start; }
.native-shell .patient-prescription-filter .patient-register-history-image,
.native-shell .patient-prescription-filter .patient-register-history-glyph { display: grid; width: 50px; height: 46px; place-items: center; color: var(--prescription-filter-color); font-size: 26px; line-height: 1; }
.native-shell .patient-prescription-filter .patient-register-history-image img { display: block; width: 100%; height: 100%; object-fit: contain; object-position: center; pointer-events: none; filter: drop-shadow(0 7px 10px rgba(18, 43, 72, .13)); }
.native-shell .patient-prescription-filter .patient-register-history-glyph { border-radius: 16px; background: color-mix(in srgb, var(--prescription-filter-color) 11%, #fff); font-weight: 950; }
.native-shell .patient-prescription-filter b { max-width: 100%; overflow: hidden; color: #082441; font-size: 12px; font-weight: 950; line-height: 1.05; text-overflow: ellipsis; }
.native-shell .patient-prescription-filter.is-active { border-color: #0aa89e !important; background: linear-gradient(150deg, #eafffa, #fff) !important; color: #082441 !important; box-shadow: 0 18px 36px rgba(10, 158, 145, .11) !important; }
