.native-shell .patient-prescription-filter-active { --prescription-filter-color: #10a75a; }
.native-shell .patient-prescription-filter-expired { --prescription-filter-color: #f23d3d; }
.native-shell .patient-prescription-filter-redeemed { --prescription-filter-color: #007d79; }
.native-shell .patient-prescription-filter-partial { --prescription-filter-color: #f2a900; }
.native-shell .patient-prescription-card-list { display: grid; gap: 18px; min-width: 0; }
.native-shell .patient-prescription-card {
