.institution-service-editor textarea, .institution-service-editor input, .institution-contract-summary input { width: 100%; padding: 11px; border: 1px solid #d1d9d7; border-radius: 7px; background: #fff; font: inherit; }
.institution-service-editor textarea { min-height: 84px; resize: vertical; }
.institution-service-edit-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.institution-service-contract-file { font-size: 11px; }
.institution-service-active-units { display: grid; gap: 12px; padding: 14px; border: 1px solid #d8dedd; border-radius: 7px; }
