.institution-service-active-units > header p { margin: 0; }
.institution-service-active-units > header p { margin-top: 4px; color: #66716f; }
.institution-service-active-search { display: grid; gap: 6px; font-size: 11px; font-weight: 800; }
.institution-service-active-search input { width: 100%; padding: 10px 12px; border: 1px solid #d1d9d7; border-radius: 7px; background: #fff; }
.institution-service-active-selection { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px; border: 1px solid #d8dedd; border-radius: 7px; }
.institution-service-active-selection > div { display: flex; gap: 8px; }
.institution-service-active-selection button { padding: 9px 13px; border-radius: 7px; }
.institution-service-active-list { max-height: 390px; overflow-y: auto; border: 1px solid #d8dedd; border-radius: 7px; }
.institution-service-active-list > label { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; padding: 11px 14px; border-bottom: 1px solid #dde2e1; }
.institution-service-active-list > label[hidden] { display: none; }
.institution-service-active-list input { width: 17px; height: 17px; }
.institution-service-active-list span strong,
.institution-service-active-list span small { display: block; }
.institution-service-active-list span small,
.institution-service-active-list em { color: #66716f; font-size: 10px; font-style: normal; }
.institution-service-editor > footer { display: flex; justify-content: flex-end; gap: 8px; }
.institution-service-editor > footer button, .institution-contract-summary > button { padding: 11px 18px; border-radius: 7px; }
.institution-service-editor button.is-primary, .institution-contract-summary button.is-primary { border-color: #007d79; color: #fff; background: #007d79; }
.institution-service-detail-title { margin-bottom: 14px; padding: 16px; }
.institution-contract-layout { display: grid; grid-template-columns: 1.4fr 1fr; gap: 14px; }
.institution-contract-preview, .institution-contract-summary { padding: 16px; }
.institution-contract-preview { display: grid; min-height: 680px; grid-template-rows: auto 1fr auto; gap: 16px; }
.institution-contract-document { width: min(570px, 100%); min-height: 350px; align-self: center; justify-self: center; padding: 48px; border: 14px solid #333; background: #fff; }
