.unit-profile-layout { display: grid; grid-template-columns: minmax(0, .86fr) minmax(0, 1fr); gap: 14px; align-items: start; }
.unit-profile-card { overflow: hidden; border: 1px solid #d4dcda; border-radius: 8px; background: #fff; color: #111; }
.unit-profile-card > header { padding: 16px 18px; border-bottom: 1px solid #d4dcda; }
.unit-profile-card > header h2, .unit-profile-card > header p { margin: 0; }
.unit-profile-card > header h2 { font-size: 14px; }
.unit-profile-card > header p { margin-top: 3px; color: #66716f; font-size: 11px; }
.unit-profile-form { display: grid; gap: 12px; padding: 16px 18px; }
.unit-profile-form > label { display: grid; gap: 6px; color: #596562; font-size: 10px; font-weight: 800; }
.unit-profile-form input[type="text"], .unit-profile-form input:not([type]), .unit-profile-form textarea { width: 100%; box-sizing: border-box; padding: 10px 12px; border: 1px solid #ced8d6; border-radius: 7px; background: #fff; font: inherit; }
.unit-profile-form textarea { min-height: 82px; resize: vertical; }
.unit-profile-image-row { display: grid; grid-template-columns: 135px 1fr; gap: 14px; align-items: center; }
.unit-profile-image-box { display: grid; min-height: 132px; place-items: center; overflow: hidden; border: 1px solid #ced8d6; border-radius: 7px; background: #f7f9f8; color: #53605e; font-weight: 800; }
.unit-profile-image-box img { width: 100%; height: 132px; object-fit: cover; }
.unit-profile-image-row > div:last-child { display: grid; gap: 10px; }
.unit-profile-remove { display: inline-flex; width: fit-content; align-items: center; gap: 6px; padding: 8px 10px; border: 1px solid #ced8d6; border-radius: 6px; background: #fff; font-size: 10px; font-weight: 800; }
.unit-profile-form > button { width: fit-content; min-width: 150px; padding: 11px 18px; border: 1px solid #007d79; border-radius: 7px; color: #fff; background: #007d79; font-weight: 800; }
